WITH scored AS (SELECT id, supplier_name, LAG(rating, 2, 0) OVER w_grp AS prev_rating, ROUND(rating / SUM(rating) OVER (PARTITION BY city), 4) AS rating_share, RANK() OVER (PARTITION BY city ORDER BY rating NULLS FIRST) AS rating_rank, AVG(rating) OVER w_ordered AS rating_avg_3, NTILE(3) OVER w_grp AS rating_bucket FROM suppliers WINDOW w_grp AS (PARTITION BY country ORDER BY rating, id), w_ordered AS (PARTITION BY city, country ORDER BY rating, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW)) SELECT id, supplier_name, prev_rating, rating_share, rating_avg_3, rating_bucket FROM scored ORDER BY prev_rating DESC;
